// ==== CONFIG — every placeholder a human must fill lives here ====
// See booking/README.md section 4 for the full field-by-field checklist.
return [{
  json: {
    timezone: 'Europe/Lisbon',
    quorumN: 2,
    meetingMin: 30,
    bufferMin: 15,
    slotStepMin: 30,
    minLeadHours: 12,
    horizonDays: 14,
    // Luxon weekday: 1=Mon .. 7=Sun
    businessHours: {
      1: [['10:00', '13:00'], ['14:00', '18:00']],
      2: [['10:00', '13:00'], ['14:00', '18:00']],
      3: [['10:00', '13:00'], ['14:00', '18:00']],
      4: [['10:00', '13:00'], ['14:00', '18:00']],
      5: [['10:00', '13:00'], ['14:00', '18:00']]
    },
    pacing: { 0: 2, 1: 3, default: 3 },
    // PLACEHOLDER: fill with the 3 real people on rotation.
    people: [
      { name: 'PLACEHOLDER_NAME_1', email: 'PLACEHOLDER_EMAIL_1@vektrum.agency', calendars: ['PLACEHOLDER_CALENDAR_ID_1'] },
      { name: 'PLACEHOLDER_NAME_2', email: 'PLACEHOLDER_EMAIL_2@vektrum.agency', calendars: ['PLACEHOLDER_CALENDAR_ID_2'] },
      { name: 'PLACEHOLDER_NAME_3', email: 'PLACEHOLDER_EMAIL_3@vektrum.agency', calendars: ['PLACEHOLDER_CALENDAR_ID_3'] }
    ],
    // PLACEHOLDER: real PT-holidays calendar ID + Vektrum PTO calendar ID.
    blockingCalendars: ['PLACEHOLDER_PT_HOLIDAYS_CALENDAR_ID', 'PLACEHOLDER_VEKTRUM_PTO_CALENDAR_ID'],
    // PLACEHOLDER: calendar ID confirmed bookings get written to.
    bookingCalendarId: 'PLACEHOLDER_BOOKING_CALENDAR_ID'
  }
}];

const CFG = $('Config').first().json;
const now = DateTime.now().setZone(CFG.timezone);
const items = [];
for (const p of CFG.people) for (const c of p.calendars) items.push({ id: c });
for (const c of CFG.blockingCalendars) items.push({ id: c });
return [{
  json: {
    timeMin: now.toUTC().toISO(),
    timeMax: now.plus({ days: CFG.horizonDays }).toUTC().toISO(),
    timeZone: CFG.timezone,
    items
  }
}];

// ==== Slot engine — byte-identical to booking/slot-engine.js's computeSlots pipeline. ====
// Luxon `DateTime` is a GLOBAL inside n8n Code nodes — do not require/import it here.
const CFG = $('Config').first().json;
const fbRaw = $json.calendars;
const now = DateTime.now().setZone(CFG.timezone);
const fb = {};
for (const [id, v] of Object.entries(fbRaw)) fb[id] = v.busy || [];

const hm = (s) => ({ hour: +s.slice(0, 2), minute: +s.slice(3, 5), second: 0, millisecond: 0 });

function candidates() {
  const earliest = now.plus({ hours: CFG.minLeadHours });
  const horizon = now.plus({ days: CFG.horizonDays });
  const out = [];
  let day = now.startOf('day');
  while (day < horizon) {
    for (const [s, e] of (CFG.businessHours[day.weekday] || [])) {
      let cur = day.set(hm(s));
      const win = day.set(hm(e));
      while (cur.plus({ minutes: CFG.meetingMin }) <= win) {
        const st = cur, en = cur.plus({ minutes: CFG.meetingMin });
        if (st >= earliest) out.push({ start: st, end: en });
        cur = cur.plus({ minutes: CFG.slotStepMin });
      }
    }
    day = day.plus({ days: 1 });
  }
  return out;
}

function busyOverlaps(iv, st, en, buf) {
  return (iv || []).some((x) => {
    const bS = DateTime.fromISO(x.start).minus({ minutes: buf });
    const bE = DateTime.fromISO(x.end).plus({ minutes: buf });
    return st < bE && en > bS;
  });
}

function evaluate(slot) {
  for (const c of CFG.blockingCalendars) {
    if (busyOverlaps(fb[c], slot.start, slot.end, 0)) return { ok: false };
  }
  let free = 0;
  const members = [];
  for (const p of CFG.people) {
    const busy = p.calendars.some((c) => busyOverlaps(fb[c], slot.start, slot.end, CFG.bufferMin));
    if (!busy) { free++; members.push(p.email); }
  }
  return { ok: free >= CFG.quorumN, members };
}

function pace(q) {
  const ws = now.startOf('week');
  const b = {};
  for (const s of q) {
    const off = Math.floor(s.start.diff(ws, 'weeks').weeks);
    (b[off] ??= []).push(s);
  }
  const out = [];
  for (const off of Object.keys(b).map(Number).sort((a, z) => a - z)) {
    const lim = CFG.pacing[off] ?? CFG.pacing.default;
    b[off].sort((a, z) => a.start - z.start);
    for (const s of b[off].slice(0, lim)) {
      out.push({
        startUTC: s.start.toUTC().toISO(),
        endUTC: s.end.toUTC().toISO(),
        label: s.start.setLocale('pt').toFormat("cccc d 'de' LLL 'às' HH:mm"),
        weekOffset: off,
        freeMembers: s.members
      });
    }
  }
  return out;
}

const qualified = candidates().map((s) => ({ ...s, ...evaluate(s) })).filter((s) => s.ok);
const slots = pace(qualified).map(({ freeMembers, ...pub }) => pub);
return [{ json: { timezone: CFG.timezone, slots } }];

// ==== Validate input — responds 400 on first failure via error thrown to caller's own IF, ====
// or simply pass-through with { valid, reason }. Here we set json.valid for a following IF.
const CFG = $('Config').first().json;
const b = $json.body || {};
const now = DateTime.now().setZone(CFG.timezone);

function fail(reason) { return [{ json: { valid: false, reason } }]; }

if (!b.name || typeof b.name !== 'string' || !b.name.trim()) return fail('missing_name');
if (!b.email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(b.email)) return fail('invalid_email');
if (!b.startUTC) return fail('missing_start');

const start = DateTime.fromISO(b.startUTC).setZone(CFG.timezone);
if (!start.isValid) return fail('invalid_start');
if (start <= now) return fail('start_not_future');

const end = start.plus({ minutes: CFG.meetingMin });

// Aligned to grid: minutes-from-midnight must be a multiple of slotStepMin.
const dayStart = start.startOf('day');
const minutesFromMidnight = start.diff(dayStart, 'minutes').minutes;
if (minutesFromMidnight % CFG.slotStepMin !== 0) return fail('not_on_grid');

// Inside a business-hours window for its weekday.
const hm = (s) => ({ hour: +s.slice(0, 2), minute: +s.slice(3, 5), second: 0, millisecond: 0 });
const windows = CFG.businessHours[start.weekday] || [];
const inWindow = windows.some(([s, e]) => {
  const ws = dayStart.set(hm(s)), we = dayStart.set(hm(e));
  return start >= ws && end <= we;
});
if (!inWindow) return fail('outside_business_hours');

// Within horizon.
if (start > now.plus({ days: CFG.horizonDays })) return fail('beyond_horizon');

return [{ json: { valid: true, name: b.name.trim(), email: b.email, note: b.note || '', lang: b.lang || 'pt', startUTC: start.toUTC().toISO(), endUTC: end.toUTC().toISO() } }];

