    bookingCalendarId: 'PLACEHOLDER_BOOKING_CALENDAR_ID'
  }
}];

// Build a freeBusy body scoped to the ONE requested slot, padded by CFG.bufferMin.
const CFG = $('Config1').first().json;
const v = $('Validate input').first().json;
const start = DateTime.fromISO(v.startUTC).minus({ minutes: CFG.bufferMin });
const end = DateTime.fromISO(v.endUTC).plus({ minutes: CFG.bufferMin });
const items = [];
for (const p of CFG.people) for (const c of p.calendars) items.push({ id: c });
for (const c of CFG.blockingCalendars) items.push({ id: c });
return [{
  json: {
    timeMin: start.toUTC().toISO(),
    timeMax: end.toUTC().toISO(),
    timeZone: CFG.timezone,
    items
  }
}];

// Reuse evaluate() from slot-engine.js against the single requested slot.
const CFG = $('Config1').first().json;
