  if (!busy) { free++; members.push(p.email); }
}
const ok = free >= CFG.quorumN;
return [{ json: { ok, members, name: v.name, email: v.email, note: v.note, lang: v.lang, startUTC: v.startUTC, endUTC: v.endUTC } }];

// Slot taken — recompute the full paced list to hand back with the 409, using a fresh freeBusy
